    static class SparseTable {
        private long[][] st;
        private int[] log;

        SparseTable(long[] arr) {
            int n = arr.length;
            st = new long[n][25];
            log = new int[n + 2];
            build_log(n + 1);
            build(arr);
        }

        private void build(long[] arr) {
            int n = arr.length;
            for (int i = n - 1; i >= 0; i--) {
                for (int j = 0; j < 25; j++) {
                    int r = i + (1 << j) - 1;
                    if (r >= n) break;
                    if (j == 0) st[i][j] = arr[i];
                    else st[i][j] = Math.min(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);
                }
            }
        }

        public long gcd(long a, long b) {
            if (a == 0) return b;
            return gcd(b % a, a);
        }

        public long query(int l, int r) {
            int w = r - l + 1;
            int power = log[w];
            return Math.min(st[l][power], st[r - (1 << power) + 1][power]);
        }

        void build_log(int n) {
            log[1] = 0;
            for (int i = 2; i <= n; i++) {
                log[i] = 1 + log[i / 2];
            }
        }
    }

