        boolean hasX = false;
        for (char cc : arr) {
            if (cc == 'X') {
                hasX = true;
                break;
            }
        }

        long tot = 0;
        if (hasX) {
            for (int i = 0; i < 10; i++) {
                char[] temp = input.toCharArray();
                if (temp[0] == 'X' && i == 0) continue;
                for (int j = 0; j < n; j++) {
                    if (temp[j] == 'X') {
                        temp[j] = (char) (i + '0');
