            flag = false;
            long back = back(arr);
            long pre = 1;
            for (int j = 0; j < n - 2; j++) {
                if (arr[j] == '_') {
                    if (j == 0) pre *= 9;
                    else pre *= 10;
                }
            }
            tot += pre * back;
            if (pre == 1 && flag) {
