                return 1;
            } else return 0;
        } else if (arr[n - 1] == '_' && arr[n - 2] == '_') {
            flag = true;
            return 4;
        } else if (arr[n - 1] == '_') {
            if (arr[n - 2] == '2' || arr[n - 2] == '0' || arr[n - 2] == '7' || arr[n - 2] == '5') {
                if (arr[n - 2] == '0') flag = true;
                return 1;
            } else return 0;
        } else {
            if (arr[n - 1] == '0' || arr[n - 1] == '5') {
                if (arr[n - 1] == '0') flag = true;
                return 2;
            } else return 0;
        }
    }

    static boolean fnc(char[] arr, int i) {
        return arr[i] != '_';
    }
